package vn.svframe.svframelib.api.crafting.ingredients; import java.util.*; public class ShapelessRequester { private final int id; private final SVFrameIngredient ingredient; private final HashMap<Integer,ShapelessItem> dibbed=new HashMap<>(); public ShapelessRequester(int id,SVFrameIngredient ingredient){this.id=id;this.ingredient=ingredient;} public int getRequestIdentifier(){return id;} public boolean isFulfilled(){return !dibbed.isEmpty();} public SVFrameIngredient getIngredient(){return ingredient;} public HashMap<Integer,ShapelessItem> getDibbed(){return new HashMap<>(dibbed);} public void claim(ShapelessItem item){dibbed.put(item.getOperationalIdentifier(),item);item.claimDibs(this);} }
